// The text of src/platform/templates.ts: the files under templates/.chernabog/, which
// init scaffolds, and the flows and prompts of packages/recipes/
// (@chernabog/recipes), which a recipe brings. A test renders it again to
// check the generated file is current.

import { fileURLToPath } from "node:url";

import { printJson } from "@chernabog/sdk";
import * as Arr from "effect/Array";
import * as Effect from "effect/Effect";
import * as FileSystem from "effect/FileSystem";
import * as Order from "effect/Order";

export const templatesRoot = fileURLToPath(new URL("../", import.meta.url));

// Each generated constant, and the directories under the repo it holds, by
// the path each is keyed under.
const SOURCES = [
  ["TEMPLATES", [["templates/.chernabog/", ""]]],
  [
    "RECIPE_FILES",
    [
      ["packages/recipes/flows/", "flows/"],
      ["packages/recipes/prompts/", "prompts/"],
    ],
  ],
] as const;

const filesUnder = (root: string, prefix: string) =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem;
    const entries = yield* fs.readDirectory(root, { recursive: true });
    const files: Array<string> = [];

    for (const entry of Arr.sort(entries, Order.String)) {
      if ((yield* fs.stat(`${root}${entry}`)).type === "File") {
        files.push(entry);
      }
    }

    const contents = yield* Effect.forEach(files, (file) => fs.readFileString(`${root}${file}`));

    return files.map(
      (file, index) => `  ${printJson(`${prefix}${file}`)}: ${printJson(contents[index] ?? "")},`,
    );
  });

export const renderTemplates = (root: string) =>
  Effect.gen(function* () {
    const blocks = yield* Effect.forEach(SOURCES, ([name, directories]) =>
      Effect.map(
        Effect.forEach(directories, ([directory, prefix]) =>
          filesUnder(`${root}${directory}`, prefix),
        ),
        (entries) => ({ name, entries: entries.flat() }),
      ),
    );

    const lines = [
      "// Generated by scripts/gen-templates.ts from templates/ and packages/recipes/. Do not edit.",
      ...blocks.flatMap(({ entries, name }) => [
        "",
        `export const ${name} = {`,
        ...entries,
        "} as const;",
      ]),
    ];

    return {
      count: blocks.reduce((total, { entries }) => total + entries.length, 0),
      text: `${lines.join("\n")}\n`,
    };
  });
